from dataclasses import dataclass

@dataclass(frozen=True)
class Get: key: str
@dataclass(frozen=True)
class Put: key: str; value: int

def run(op, store):
    match op:
        case Get(key=k):          return store.read(k)
        case Put(key=k, value=v): return store.write(k, v)
        case _: raise TypeError(f"unhandled op: {op!r}")

from functools import singledispatch

@singledispatch
def run(op, store):
    raise TypeError(f"unhandled op: {op!r}")

@run.register
def _(op: Get, store): return store.read(op.key)

@run.register
def _(op: Put, store): return store.write(op.key, op.value)
